def m01_l020_ai_dlya_ucheby_s008_rag_answer_solve(query, chunks):
    query_words = set(query.lower().split())
    best = None
    best_score = 0
    for chunk in chunks:
        score = len(query_words & set(chunk['text'].lower().split()))
        if score > best_score:
            best = chunk
            best_score = score
    if best_score == 0:
        return {'answer': 'Не знаю', 'source': None, 'score': 0}
    return {'answer': best['text'], 'source': best['source'], 'score': best_score}

