def m01_l020_ai_dlya_ucheby_s009_graph_state_solve(state):
    new_state = dict(state)
    if new_state.get('answer'):
        new_state['node'] = 'finish'
    elif new_state.get('error') and new_state.get('attempts', 0) < 2:
        new_state['attempts'] = new_state.get('attempts', 0) + 1
        new_state['node'] = 'retry'
    else:
        new_state['node'] = 'retrieve'
    return new_state

